package com.codeguardian.service.rules; import com.codeguardian.entity.Finding; import org.springframework.stereotype.Service; import java.util.*; import java.util.regex.*;
@Service public class RuleEngineService{private static final Map<String,List<RuleDefinition>> TEMPLATES=Map.of("ALIBABA",List.of(rule("Avoid System.out", "Use a logger instead of System.out", "System\\.out\\.print", "LOW"),rule("Avoid empty catch", "Handle or log caught exceptions", "catch\\s*\\([^)]*\\)\\s*\\{\\s*\\}", "MEDIUM")),"GOOGLE",List.of(rule("Line too long","Keep Java lines at a readable length","(?m)^.{101,}$","LOW")),"AIRBNB",List.of(rule("Use strict equality","Prefer === over ==","(?<![=!])==(?!=)","MEDIUM"),rule("Avoid var","Use let or const instead of var","\\bvar\\s+","LOW")),"PEP8",List.of(rule("Line too long","PEP8 limits lines to 79 characters","(?m)^.{80,}$","LOW"),rule("Tabs used","Use four spaces instead of tabs","\\t","MEDIUM")));private static RuleDefinition rule(String n,String d,String p,String s){return RuleDefinition.builder().name(n).description(d).pattern(p).severity(s).suggestion("Follow the selected style guide.").build();}public List<Finding> reviewWithTemplate(String code,String language,String template){List<Finding> out=new ArrayList<>();for(RuleDefinition r:TEMPLATES.getOrDefault(template==null?"":template.toUpperCase(),List.of())){Matcher m=Pattern.compile(r.getPattern(),Pattern.MULTILINE).matcher(code==null?"":code);while(m.find()){int line=1+(int)(code.substring(0,m.start()).chars().filter(x->x=='\n').count());out.add(Finding.builder().severity(r.getSeverity()).title(r.getName()).location("Line "+line).startLine(line).endLine(line).description(r.getDescription()).suggestion(r.getSuggestion()).category("CODE_STYLE").build());}}return out;}public Set<String> templates(){return TEMPLATES.keySet();}}
